import re
import string
from nltk.stem import PorterStemmer
from collections import Counter

STEMMER = PorterStemmer()

def task_func(content):
    if not content:
        return {}

    # Extract word-like tokens and ignore surrounding punctuation.
    words = re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?", str(content))
    if len(words) <= 1:
        return {}

    # Stem every word except the last one.
    stems = (STEMMER.stem(word.lower()) for word in words[:-1])

    return dict(Counter(stems))
